from __future__ import annotations

from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple

from . import fsops

CREATE = "create"
UPDATE = "update"
DELETE = "delete"
KEEP = "keep"


@dataclass
class PlanEntry:
    """计划中的一条动作。"""

    action: str
    relpath: str
    source: Optional[str] = None
    target: Optional[str] = None


@dataclass
class Plan:
    """一次同步的完整计划。"""

    entries: List[PlanEntry] = field(default_factory=list)

    def actions(self) -> List[str]:
        return [entry.action for entry in self.entries]

    def by_action(self, action: str) -> List[PlanEntry]:
        return [entry for entry in self.entries if entry.action == action]


def needs_update(source_path: str, target_path: str) -> bool:
    """目标文件是否需要被源文件覆盖。

    判定依据是**内容本身**：大小不同、或者大小相同而字节不同，都需要更新。
    修改时间不参与判定——上游工具可能就地改写文件却把原来的时间戳保留下来，
    只看大小与时间会把这种文件误判成“没有变化”。
    """
    source_signature = fsops.stat_signature(source_path)
    if source_signature is None:
        # 源文件读不出来（不存在或被占用），无从更新。
        return False
    target_signature = fsops.stat_signature(target_path)
    if target_signature is None:
        return True
    if source_signature[0] != target_signature[0]:
        # 大小已经不同，不必再读内容。
        return True
    return not fsops.content_equal(source_path, target_path)


def _index(entries: Dict[str, str]) -> Dict[str, Tuple[str, str]]:
    """把 ``{相对路径: 绝对路径}`` 转成 ``{路径键: (相对路径, 绝对路径)}``。

    路径键由 :func:`wsync.fsops.path_key` 决定，在不区分大小写的文件系统上
    ``Report.PDF`` 与 ``report.pdf`` 会落到同一个键，于是被认成同一个条目，
    而不是“新建一个 + 删掉一个”。
    """
    indexed: Dict[str, Tuple[str, str]] = {}
    for relpath, full in entries.items():
        indexed.setdefault(fsops.path_key(relpath), (relpath, full))
    return indexed


def build_plan(source_root: str, target_root: str) -> Plan:
    """计算从 ``source_root`` 到 ``target_root`` 的镜像同步计划。"""
    source_files = fsops.list_entries(source_root)
    target_files = fsops.list_entries(target_root)

    source_index = _index(source_files)
    target_index = _index(target_files)

    entries: List[PlanEntry] = []

    for relpath in sorted(source_files):
        key = fsops.path_key(relpath)
        match = target_index.get(key)
        if match is None:
            entries.append(
                PlanEntry(
                    CREATE,
                    relpath,
                    source_files[relpath],
                    fsops.join(target_root, relpath),
                )
            )
        elif needs_update(source_files[relpath], match[1]):
            entries.append(
                PlanEntry(UPDATE, relpath, source_files[relpath], match[1])
            )
        else:
            entries.append(
                PlanEntry(KEEP, relpath, source_files[relpath], match[1])
            )

    for relpath in sorted(target_files):
        if fsops.path_key(relpath) not in source_index:
            entries.append(PlanEntry(DELETE, relpath, None, target_files[relpath]))

    return Plan(entries)

